import {api} from './disk-store.js';
export function setupRepositoryUI({getState,disk,modal,field,button,icon,toast,esc,reload}){
 const $=selector=>document.querySelector(selector);
 const authFields=()=>`<details class="repo-auth"><summary>仓库认证（私人仓库可填写）</summary><div class="form-grid">${field('username','账号（可选）')}${field('password','密码 / Token（只保留在本次服务会话）','','password')}</div><p>认证内容不会写入项目文件、仓库配置或安装包。SSH 使用本机密钥；HTTPS 也可使用系统已有的凭据。</p></details>`;
 const feedback='<p id="repo-feedback" class="repo-feedback" role="status"></p>';
 const actions=(label,form)=>`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" type="submit" form="${form}">${label}</button>`;
 const projectName=id=>getState().projects.find(p=>p.id===id)?.name||disk.issues.find(p=>p.id===id)?.name||id;
 function linkDialog(){modal('从仓库链接导入项目',`<form id="repo-link-form"><p class="notice">只为这个项目检出独立工作副本。仓库链接保存在项目目录中，不绑定整个工作台。</p><div class="form-grid">${field('type','版本控制类型','git','select',[['git','Git'],['svn','SVN']])}${field('branch','Git 分支（可选，留空使用仓库默认）')}</div>${field('url','仓库链接（HTTPS / SSH / SVN / file）')}${field('contentPath','仓库内项目路径（可选，多项目仓库时填写）')}<label class="repo-check"><input type="checkbox" name="initializeEmpty">在空仓库创建新项目</label>${field('projectName','空仓库的新项目名称（可选）')}${authFields()}${feedback}</form>`,actions('检出并加入项目库','repo-link-form'));}
 function attachDialog(){modal('关联独立项目文件夹',`<form id="repo-attach-form"><p class="notice">关联已有项目，不移动或覆盖原目录。文件夹应包含 project.json；也支持只含一个项目的旧版 Project 目录。</p>${field('directory','项目文件夹完整路径')}<label class="repo-check"><input type="checkbox" name="replace">同一项目已存在时，更新本机的目录关联</label>${feedback}</form>`,actions('读取并关联','repo-attach-form'));}
 async function repoDialog(id){if(disk.dirty&&!await disk.flush())return;try{const cfg=await api(`/api/projects/${id}/status`);if(cfg.type!=='local'){modal('项目仓库 · '+esc(projectName(id)),`<div class="repo-overview"><span class="tag">${esc(cfg.type.toUpperCase())}</span><p>此链接只作用于当前项目。</p><label>仓库链接</label><pre>${esc(cfg.url)}</pre>${cfg.branch?`<label>分支</label><pre>${esc(cfg.branch)}</pre>`:''}<label>项目目录</label><pre>${esc(cfg.directory)}</pre><p>更换仓库请从新链接导入，或关联对应的已有工作副本。已绑定项目不会误上传到其他链接。</p></div>`,`<button class="danger-link" data-project-detach="${id}">移除本机关联</button><button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-project-upload="${id}">${icon('upload')}上传此项目</button>`);return;}
 modal('绑定独立仓库 · '+esc(projectName(id)),`<form id="repo-bind-form" data-id="${id}"><p class="notice">绑定一个空仓库。非空仓库请用「链接导入」，避免覆盖已有历史。旧版工作台内的项目会先复制到独立目录，原副本保留。</p><div class="form-grid">${field('type','版本控制类型','git','select',[['git','Git'],['svn','SVN']])}${field('branch','Git 分支','main')}</div>${field('url','当前项目的仓库链接')}<div class="form-grid">${field('authorName','Git 提交者姓名')}${field('authorEmail','Git 提交者邮箱','','email')}</div>${authFields()}${feedback}</form>`,actions('绑定此项目','repo-bind-form'));}catch(error){toast(error.message);}}
 async function uploadDialog(id){if(disk.dirty&&!await disk.flush())return;try{const cfg=await api(`/api/projects/${id}/status`);if(cfg.type==='local')return repoDialog(id);modal('上传项目 · '+esc(projectName(id)),`<form id="repo-upload-form" data-id="${id}"><div class="repo-upload-summary"><span class="tag">${esc(cfg.type.toUpperCase())}</span><strong>${cfg.changes.length} 个待提交变更</strong><p>${esc(cfg.url)}${cfg.branch?' · '+esc(cfg.branch):''}</p></div>${cfg.conflicts.length?'<p class="notice">存在未解决冲突，请先处理冲突后上传。</p>':''}<div class="repo-changes">${cfg.changes.slice(0,80).map(c=>`<div><b>${esc(c.status)}</b><span>${esc(c.path)}</span></div>`).join('')||'<p>没有工作区变更；Git 仍会尝试推送尚未上传的本地提交。</p>'}</div>${field('message','提交说明','更新项目设计内容','textarea')}${cfg.type==='git'?`<div class="form-grid">${field('authorName','提交者姓名',cfg.authorName||'')}${field('authorEmail','提交者邮箱',cfg.authorEmail||'','email')}</div>`:''}${authFields()}<p class="form-help">Git：只提交此项目并推送绑定分支。SVN：提交此项目的新增、修改和删除。不会强制推送或自动覆盖冲突。</p>${feedback}</form>`,actions(cfg.type==='git'?'提交并推送':'提交到 SVN','repo-upload-form'));}catch(error){toast(error.message);}}
 function updateDialog(id){modal('更新项目 · '+esc(projectName(id)),`<form id="repo-update-form" data-id="${id}"><p class="notice">从当前项目绑定的仓库获取更新。请先上传或备份本地修改；工作台会拒绝覆盖尚未提交的内容。</p>${authFields()}${feedback}</form>`,actions('更新此项目','repo-update-form'));}
 function busy(value,message=''){document.querySelectorAll('#modal-root input,#modal-root select,#modal-root textarea,#modal-root button').forEach(el=>el.disabled=value);const result=$('#repo-feedback');if(result){result.textContent=message;result.classList.toggle('working',value);}}
 document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.action==='import-link')linkDialog();if(el.dataset.action==='attach-folder')attachDialog();if(el.dataset.projectRepo)void repoDialog(el.dataset.projectRepo);if(el.dataset.projectUpload)void uploadDialog(el.dataset.projectUpload);if(el.dataset.projectUpdate)updateDialog(el.dataset.projectUpdate);if(el.dataset.projectDetach){const id=el.dataset.projectDetach;modal('移除本机关联',`<p class="notice">仅从当前电脑的项目库移除「${esc(projectName(id))}」。项目文件、Git/SVN 工作副本和远程内容保持不动。</p>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-confirm-detach="${id}">移除本机关联</button>`);}if(el.dataset.confirmDetach)void api(`/api/projects/${el.dataset.confirmDetach}/detach`,'POST',{}).then(async result=>{await reload();toast(result.message);}).catch(error=>toast(error.message));if(el.dataset.action==='tools-info')void api('/api/tools').then(tools=>modal('内置运行依赖',`<div class="repo-overview"><p>EXE 优先使用 Runtime 文件夹中的组件，不修改全局 PATH。</p>${Object.entries(tools).map(([name,data])=>`<p><strong>${esc(name.toUpperCase())}</strong> · ${data.available?esc(data.version)+(data.bundled?' · 已内置':' · 系统版本'):'不可用：'+esc(data.error)}</p>`).join('')}</div>`,`<button class="btn primary" data-action="close-modal">完成</button>`)).catch(error=>toast(error.message));});
 document.addEventListener('submit',async e=>{const form=e.target;if(!['repo-link-form','repo-bind-form','repo-upload-form','repo-update-form','repo-attach-form'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));const credentials={username:data.username||'',password:data.password||''};delete data.username;delete data.password;const id=form.dataset.id;busy(true,form.id==='repo-link-form'?'正在检出独立项目，请稍候…':form.id==='repo-upload-form'?'正在上传此项目，请保持工作台开启…':'正在处理项目工作副本…');try{if(disk.dirty&&!await disk.flush())throw new Error('有修改尚未保存，请先处理保存提示。');let result;
  if(form.id==='repo-link-form')result=await api('/api/projects/link','POST',{...data,credentials,name:data.projectName,initializeEmpty:Boolean(data.initializeEmpty)});
  else if(form.id==='repo-attach-form')result=await api('/api/projects/attach','POST',{directory:data.directory,replace:Boolean(data.replace)});
  else if(form.id==='repo-bind-form')result=await api(`/api/projects/${id}/bind`,'POST',{...data,credentials});
  else if(form.id==='repo-upload-form')result=await api(`/api/projects/${id}/upload`,'POST',{...data,credentials});
  else result=await api(`/api/projects/${id}/update`,'POST',{credentials});
  await reload();toast(result.message||'项目工作副本已就绪，仓库链接仅属于此项目。');
 }catch(error){busy(false,error.message);}});
}
